fn bin_search(a: &[i32], k: i32) -> bool {
    let mut left: usize = 0;
    let mut right: usize = a.len(); // exclusive upper bound

    while left < right {
        let mid = left + (right - left) / 2;
        if a[mid] < k {
            left = mid + 1;
        } else {
            right = mid;
        }
    }

    left < a.len() && a[left] == k
}